      SUBROUTINE RTOROCC     TRANSFERS MATRIX R TO ROCC ----------------------------------------------------------------------      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RO.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TO.CIN'      INCLUDE 'U.CIN'      INCLUDE 'UO.CIN'C      DO 10 JK = 1, 36   10 ROL(JK) = RL(JK)      IF (NORD1 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TOL(JKM) = TL(JKM)      ENDIF      IF (NORD1 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   UOL(JKLM) = UL(JKLM)      ENDIF      RETURN      END